"""Render twelve original motion/UI keyframes. These are explicitly not product screenshots."""
from pathlib import Path
import html,json,hashlib,base64
from playwright.sync_api import sync_playwright
from PIL import Image
R=Path(__file__).resolve().parents[1]
CSS='''@font-face{font-family:Geist;src:url("FONT/Geist-Regular.ttf")}@font-face{font-family:Geist;src:url("FONT/Geist-Bold.ttf");font-weight:700}@font-face{font-family:Anton;src:url("FONT/fonts/anton-400.woff2")}@font-face{font-family:Serif;src:url("FONT/fonts/cormorantgaramond-700.woff2");font-weight:700}*{box-sizing:border-box}body{margin:0;width:1200px;height:800px;overflow:hidden;font-family:Geist,sans-serif;color:#182536}h1,h2,p{margin:0}h1{font-size:76px;line-height:1.02;letter-spacing:-3px}h2{font-size:42px;line-height:1.1;letter-spacing:-1.4px}p{font-size:25px;line-height:1.45}.eyebrow{font-size:17px;letter-spacing:3px;text-transform:uppercase;font-weight:700}.frame{width:100%;height:100%;padding:66px;position:relative;overflow:hidden}.foot{position:absolute;bottom:34px;left:66px;right:66px;display:flex;justify-content:space-between;font-size:15px;letter-spacing:1.5px;text-transform:uppercase}.pill{padding:12px 19px;display:inline-block;border-radius:40px;font-size:16px;font-weight:700}.screen{background:#fff;border:1px solid #d4dbe4;border-radius:18px;overflow:hidden;box-shadow:0 22px 55px #18253617}.bar{height:55px;border-bottom:1px solid #dce2eb;display:flex;align-items:center;padding:0 23px;gap:8px;font-size:16px}.dot{width:9px;height:9px;border-radius:50%;background:#b1bdcd}.columns{display:flex;gap:28px}.col{flex:1}.line{height:10px;background:#dce2e9;border-radius:3px;margin:13px 0}.arrow{font-size:65px;line-height:1}.label{font-size:16px;text-transform:uppercase;letter-spacing:2px}.small{font-size:18px}.panel{padding:28px;border-radius:16px}.check{color:#19957f;font-weight:700}.ui{font-size:18px}.button{padding:15px 23px;background:#185ce9;color:white;border-radius:10px;display:inline-block;font-size:20px}.cursor{position:absolute;width:0;height:0;border-left:17px solid #161c28;border-bottom:27px solid transparent;transform:rotate(-18deg);filter:drop-shadow(3px 3px 0 white)}'''
def footer(n):return f'<div class="foot"><span>Estudo de direção · infoprodutores</span><span>{n:02d} / demonstração</span></div>'
def frame(n,style,body):return f'<div class="frame" style="{style}">{body}{footer(n)}</div>'
def screen_frame(title,body):return '<div class="screen"><div class="bar"><i class="dot"></i><i class="dot"></i><i class="dot"></i><span style="margin-left:20px">'+title+'</span></div>'+body+'</div>'
def poster(good=False):
 return f'<div style="height:300px;color:#182536;background:#e9ff70;padding:{32 if good else 18}px;position:relative;border:1px solid #a8b84a"><span class="label">EXERCÍCIO</span><div style="font-family:Anton;font-size:{58 if good else 38}px;line-height:1.05;margin-top:{30 if good else 12}px;max-width:210px">FORMA<br>E RITMO</div><div style="position:absolute;right:22px;bottom:28px;width:88px;height:88px;border-radius:50%;background:#263aee"></div></div>'
def sample(n):
 if n==2:
  body='<p class="eyebrow">UMA DECISÃO. UM EFEITO VISÍVEL.</p><h1 style="font-size:54px;margin:15px 0 30px">Veja o método funcionando.</h1>'+screen_frame('Editor demonstrativo · exercício de composição','<div style="display:flex;height:420px"><aside style="width:180px;padding:25px;background:#f5f7fb"><b>Camadas</b><p class="small" style="margin-top:25px">Título</p><p class="small">Imagem</p><p class="small">Legenda</p></aside><div style="flex:1;padding:27px 60px;background:#e9eef5;position:relative">'+poster(True)+'<div class="cursor" style="left:130px;top:120px"></div></div><aside style="width:250px;padding:25px"><b>Alinhamento</b><p class="small" style="margin-top:20px">Compare a margem.</p><div style="margin-top:24px;color:#1556df;border-left:3px solid;padding-left:12px">A decisão vem antes do efeito.</div></aside></div>')
  return frame(n,'background:#f0f5fc',body)
 if n==3:
  return frame(n,'background:#f3ff65;color:#141414','<p class="eyebrow">PRÉ-REQUISITOS · SEM RODEIOS</p><h1 style="font-family:Anton;font-size:118px;line-height:.94;margin-top:45px">É PARA<br>VOCÊ?</h1><div style="position:absolute;right:65px;top:225px;width:445px;border-top:3px solid;padding-top:25px"><p style="font-size:29px"><b>Para começar</b><br>Conheça o ponto de partida.</p><p style="margin-top:35px;font-size:29px"><b>Você precisa</b><br>Confira o que a prática exige.</p><div style="margin-top:38px;font-size:67px">→</div></div>')
 if n==5:
  return frame(n,'background:#e7e8f3','<p class="eyebrow">REPLAY TÉCNICO</p><h1 style="font-size:58px;margin:18px 0 32px">O erro está aqui.</h1><div class="columns"><div class="col panel" style="background:white"><p class="label" style="margin-bottom:15px">01 · observar</p>'+poster(False).replace('#e9ff70','#ffd0aa')+'</div><div class="arrow" style="align-self:center;color:#4343bf">→</div><div class="col panel" style="background:white"><p class="label" style="margin-bottom:15px">02 · corrigir e conferir</p>'+poster(True).replace('#e9ff70','#ffd0aa')+'</div></div><p class="small" style="margin-top:18px">Mesmo exercício. Um critério de hierarquia.</p>')
 if n==8:
  return frame(n,'background:#152b2c;color:#e7f5ef','<div style="width:12px;height:170px;background:#a8e5b4;position:absolute;top:0;left:75px"></div><div style="margin-left:65px;margin-top:100px"><p class="eyebrow">RETOMADA SEM PRESSÃO</p><h1 style="font-size:92px;max-width:820px;margin-top:30px">Você pode<br>continuar daqui.</h1><div style="display:flex;align-items:center;gap:30px;margin-top:45px"><span style="font-size:58px;color:#a8e5b4">→</span><div><p>Uma tarefa, por vez.</p><p class="small" style="opacity:.65">Mostrar a etapa real do aluno na produção.</p></div></div></div>')
 if n==10:
  return frame(n,'background:#111620;color:#ecf1f8','<p class="eyebrow" style="color:#9daec5">CLÍNICA DE FEEDBACK</p><h1 style="font-size:58px;margin:20px 0 32px">O comentário vira ação.</h1><div style="display:flex;gap:28px"><div style="width:590px;background:#242e3e;padding:35px;border-radius:12px;position:relative">'+poster(True).replace('#e9ff70','#9ee6e3')+'<div style="position:absolute;left:50px;top:80px;width:280px;height:130px;border:3px solid #f898a7;border-radius:50%;transform:rotate(-7deg)"></div></div><div style="flex:1;padding-top:35px"><span class="pill" style="background:#f898a7;color:#1f2330">CRITÉRIO 01</span><h2 style="margin-top:26px">Dê espaço<br>à mensagem.</h2><p class="small" style="margin-top:20px;color:#acb7c8">Indique o trecho.<br>Explique por quê.<br>Proponha um ajuste.</p></div></div>')
 if n==11:
  return frame(n,'background:#4126c8;color:#fff','<div style="position:absolute;width:480px;height:480px;border:55px solid #6550dc;border-radius:50%;right:-150px;top:-200px"></div><p class="eyebrow">PAUSA PARA PENSAR</p><h1 style="margin:38px 0 35px;font-size:77px">O que muda<br>no enquadramento?</h1><div class="columns"><div class="col panel" style="background:#f9d55d;color:#211a45"><p class="eyebrow">A</p><h2 style="margin-top:20px">A distância<br>da câmera</h2></div><div class="col panel" style="border:2px solid #a396eb"><p class="eyebrow">B</p><h2 style="margin-top:20px">A cor<br>da legenda</h2></div></div><p class="small" style="margin-top:28px">Responda antes de ver a explicação.</p>')
 if n==15:
  return frame(n,'background:#dceeea','<div style="max-width:510px;padding-top:80px"><p class="eyebrow">AJUDA COM CONTEXTO</p><h1 style="font-size:87px;margin-top:28px">Travou?<br>Mostre onde.</h1><p style="margin-top:30px">Aula + tentativa + dúvida.</p></div><div style="position:absolute;right:90px;top:72px;width:330px;height:610px;border:10px solid #1c2d36;border-radius:45px;background:#fff;box-shadow:25px 30px 50px #436b5b25;padding:48px 22px 20px"><div style="position:absolute;top:10px;left:100px;width:110px;height:18px;border-radius:15px;background:#1c2d36"></div><h2 style="font-size:24px">Suporte · demonstração</h2><div class="panel" style="background:#e8f2f7;margin-top:25px;padding:18px"><p class="small">Em qual aula surgiu a dúvida?</p></div><div class="panel" style="background:#cef0df;margin:18px 0 0 20px;padding:18px"><p class="small">Aula de composição. Tentei alinhar o título.</p></div><p class="small" style="margin-top:25px">Anexe a tentativa</p><div style="border:1px dashed #92a9a3;border-radius:10px;padding:20px;margin-top:12px;font-size:18px">+ Imagem do exercício</div><div class="button" style="margin-top:22px;background:#1b7864">Conferir e enviar</div></div>')
 if n==18:
  return frame(n,'background:#f5f1e9;color:#232522','<p class="eyebrow">CONCLUSÃO COM CRITÉRIOS</p><div style="display:flex;gap:65px;margin-top:65px"><div style="width:590px;border:1px solid #a5a293;padding:55px 35px;text-align:center"><p class="label">MODELO DEMONSTRATIVO</p><h1 style="font-family:Serif;font-size:70px;letter-spacing:0;margin:40px 0">Certificado</h1><p class="small">Nome do participante</p><div style="height:1px;background:#a5a293;margin:30px 40px"></div><p class="small">Curso · critérios · emissão</p></div><div style="flex:1;padding-top:35px"><h2 style="font-family:Serif;font-size:46px">O que ele<br>comprova?</h2><p class="small" style="margin-top:30px">Conferir requisitos,<br>alcance e reconhecimento<br>do documento real.</p></div></div>')
 if n==19:
  return frame(n,'background:#f44b32;color:#20160e','<p class="eyebrow">A OFERTA PRECISA SER CLARA.</p><h1 style="font-family:Anton;font-size:112px;line-height:1.02;margin-top:42px">AULAS.<br><span style="color:#fff1dc">PRÁTICA.</span><br>FEEDBACK.</h1><div style="position:absolute;right:50px;bottom:170px;width:300px;transform:rotate(-5deg);background:#fff1dc;padding:28px"><p style="font-size:22px;font-weight:700">Mostre o que está<br>realmente incluído.</p></div>')
 if n==24:
  return frame(n,'background:#0d192c;color:#eff4fc','<div style="position:absolute;right:-200px;top:-140px;width:700px;height:700px;border:1px solid #315477;border-radius:50%"></div><p class="eyebrow" style="color:#5fe0d5">EDIÇÃO ATUALIZADA</p><h1 style="margin:32px 0 45px;font-size:84px">O que mudou<br>na prática?</h1><div style="display:flex;gap:20px;position:relative"><div class="panel" style="background:#1c2c43;width:300px"><p class="label">ANTES</p><p style="margin-top:20px">Aula original</p><div class="line" style="background:#3d4c65"></div><div class="line" style="width:70%;background:#3d4c65"></div></div><div class="arrow" style="align-self:center;color:#5fe0d5">→</div><div class="panel" style="border:2px solid #5fe0d5;flex:1"><p class="label" style="color:#5fe0d5">AGORA</p><p style="margin-top:20px">Nova aplicação do método</p><p class="small" style="color:#a4b4ca;margin-top:15px">Exercício e acesso devem corresponder à versão real.</p></div></div>')
 if n==25:
  rows=''.join('<tr><td>'+x+'</td><td>'+y+'</td><td>'+z+'</td></tr>' for x,y,z in [('Objetivo','Explicar uma dúvida','Definido'),('Formato','Vídeo de demonstração','Escolhido'),('Conteúdo','Uma tarefa e um critério','Em revisão'),('Próxima ação','Gravar o exemplo','Planejado')])
  return frame(n,'background:#edf2f7','<p class="eyebrow">RECURSO EM USO</p><h1 style="font-size:60px;margin:20px 0 30px">O template sai do vazio.</h1>'+screen_frame('Planejamento editorial · dados demonstrativos','<div style="padding:35px"><div style="display:flex;justify-content:space-between;margin-bottom:25px"><b class="ui">Meu primeiro exemplo</b><span class="pill" style="background:#dcf3e5;color:#245b43">ARQUIVO DEMONSTRATIVO</span></div><table style="border-collapse:collapse;width:100%;font-size:23px;text-align:left"><thead><tr style="background:#e2eaf4"><th style="padding:18px">Campo</th><th>Preenchimento</th><th>Estado</th></tr></thead><tbody>'+rows+'</tbody></table><style>td{padding:14px 18px;border-bottom:1px solid #e4e9ef}td:last-child{font-size:18px;color:#405d72}</style></div>')+'<p class="small" style="margin-top:18px">Demonstre uma aplicação, não apenas o download.</p>')
 if n==27:
  return frame(n,'background:#f1a2ad;color:#132a88','<p class="eyebrow">DESAFIO DE CRIAÇÃO</p><h1 style="font-family:Anton;font-size:105px;line-height:.98;margin-top:38px">UMA TENTATIVA.<br>UM CRITÉRIO.</h1><div style="display:flex;margin-top:50px;gap:28px"><div style="border:2px solid;padding:26px;flex:1"><p class="label">TAREFA</p><h2 style="margin-top:15px;font-size:33px">Reorganize a mensagem.</h2></div><div style="background:#132a88;color:#f4c2ca;padding:26px;flex:1"><p class="label">OBSERVE</p><h2 style="margin-top:15px;font-size:33px">O que você lê primeiro?</h2></div></div><p class="small" style="margin-top:30px">Pausa para praticar. Depois, compare e explique.</p>')
 raise ValueError(n)
if __name__=='__main__':
 nums=[2,3,5,8,10,11,15,18,19,24,25,27]
 with sync_playwright() as p:
  browser=p.chromium.launch(executable_path='/usr/bin/chromium',headless=True,args=['--no-sandbox'])
  page=browser.new_page(viewport={'width':1200,'height':800},device_scale_factor=1)
  for n in nums:
   css=CSS
   for font in ['Geist-Regular.ttf','Geist-Bold.ttf','fonts/anton-400.woff2','fonts/cormorantgaramond-700.woff2']:
    css=css.replace('FONT/'+font,'data:font/'+('ttf' if font.endswith('ttf') else 'woff2')+';base64,'+base64.b64encode((R/'dist/assets'/font).read_bytes()).decode())
   doc='<!doctype html><html lang="pt-BR"><meta charset="utf-8"><style>'+css+'</style>'+sample(n)+'</html>'
   out=R/'records'/f'infopro-ui-{n:02d}.html';out.write_text(doc)
   page.set_content(doc);page.evaluate('document.fonts.ready');page.screenshot(path=str(R/'records'/f'infopro-ui-{n:02d}.png'))
   Image.open(R/'records'/f'infopro-ui-{n:02d}.png').save(R/'dist/assets'/f'infopro-r2-{n:02d}.webp','WEBP',quality=95,method=6)
   assert page.evaluate('document.documentElement.scrollWidth')==1200
  browser.close()
 print('12 original editorial/UI studies rendered; no platform screenshot claims.')
